    public struct OWPlayer {        public int Type;        public string Name;        [MarshalAs(UnmanagedType.LPWStr)] public string FilePath;// swf file path        [MarshalAs(UnmanagedType.LPWStr)] public string RootDir; // directory with xml setting        public bool Hidden;  // input > 1 = True, 0 = False          public bool AutoPlay;        public bool FullScreen;        public bool FitToScreen;        public bool CenterToScreen;        public bool EscapeEnabled;        public new string ToString {            get {                string msg = "";                foreach (var field in typeof(OWPlayer).GetFields(BindingFlags.Public | BindingFlags.Instance)) {                    msg += String.Format("\n\t{0} = {1}", field.Name, field.GetValue(this));                }                return msg;            }        }    }